    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to Enthalpy, but math on it needs the Enthalpy first.
    /// </summary>
    public QuantityInUnit<Enthalpy> ToUnit(EnthalpyUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public Enthalpy ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "J/kg"}. Reads that (any unit of Enthalpy, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class EnthalpyJsonConverter : JsonConverter<Enthalpy>
{
    public override Enthalpy Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => Enthalpy.FromSI(QuantityJson.Read(ref reader, "Enthalpy", EnthalpyUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, Enthalpy value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, EnthalpyUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this Enthalpy value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this Enthalpy value) => new(Math.Sqrt(value.SI));

    public static Enthalpy Sum(this IEnumerable<Enthalpy> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Enthalpy.FromSI(sum);
    }

    public static Enthalpy Average(this IEnumerable<Enthalpy> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Enthalpy.FromSI(sum / count);
    }

    public static Enthalpy Min(this IEnumerable<Enthalpy> values) => Aggregate(values, Math.Min);
    public static Enthalpy Max(this IEnumerable<Enthalpy> values) => Aggregate(values, Math.Max);

    private static Enthalpy Aggregate(IEnumerable<Enthalpy> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Enthalpy.FromSI(result);
    }
}
